import{_ as r,c as o,o as e,ah as s}from"./chunks/framework.RCw5T9E9.js";const c=JSON.parse('{"title":"Экспорт и импорт","description":"","frontmatter":{"title":"Экспорт и импорт"},"headers":[],"relativePath":"ru/logs/export.md","filePath":"ru/logs/export.md"}'),n={name:"ru/logs/export.md"};function a(g,t,l,i,h,d){return e(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="экспорт-и-импорт" tabindex="-1">Экспорт и импорт <a class="header-anchor" href="#экспорт-и-импорт" aria-label="Permalink to &quot;Экспорт и импорт&quot;">​</a></h1><p>События вкладки <strong>Logs</strong> можно сохранить в <strong>HTML</strong>-отчёт и открыть снова — в любом браузере или через <strong>Import Logs</strong> в Vue Inspector. Это удобно для баг-репортов, передачи сценария коллегам и анализа вне страницы.</p><p>Общие сведения о вкладке: <a href="./general.html">Работа с логами</a>.</p><hr><h2 id="формат-экспорта" tabindex="-1">Формат экспорта <a class="header-anchor" href="#формат-экспорта" aria-label="Permalink to &quot;Формат экспорта&quot;">​</a></h2><p>Любой экспорт — один <strong>HTML</strong>-файл: статический отчёт для просмотра и структурированные данные событий, которые читает <strong>Import Logs</strong>. Отдельного экспорта в JSON нет.</p><p>Данные внутри отчёта компактные, как и в живом логе (см. <a href="./general.html#how-events-are-stored">Как хранятся события</a>): изменения стора — диффы, запрос и ответ используют одну сетевую запись, одинаковые тела хранятся один раз. Заголовки, состояния Before / After и данные запроса и ответа восстанавливаются при открытии отчёта.</p><p>У встроенных данных есть версия формата. Файлы из более новых версий Vue Inspector отклоняются с сообщением, а не читаются неверно.</p><hr><h2 id="что-именно-экспортируется" tabindex="-1">Что именно экспортируется <a class="header-anchor" href="#что-именно-экспортируется" aria-label="Permalink to &quot;Что именно экспортируется&quot;">​</a></h2><h3 id="export-logs" tabindex="-1">Export Logs <a class="header-anchor" href="#export-logs" aria-label="Permalink to &quot;Export Logs&quot;">​</a></h3><ul><li>Без выбора — все события, видимые в таблице с учётом <strong>Search</strong> и фильтра <strong>Type</strong>.</li><li>С выбором — только строки, отмеченные в колонке чекбоксов; кнопка показывает <strong>Export Logs (n)</strong>.</li><li>Сетевые события всегда экспортируются парой: если в фильтр или выбор попал только <strong>Send request</strong> или только <strong>Receive response</strong> запроса, второе событие тоже добавляется в файл.</li></ul><p>Кнопка неактивна, пока в отфильтрованном списке нет ни одного события.</p><h3 id="одно-событие" tabindex="-1">Одно событие <a class="header-anchor" href="#одно-событие" aria-label="Permalink to &quot;Одно событие&quot;">​</a></h3><p><strong>Export event</strong> в меню <strong>⋮</strong> шапки детализации или в контекстном меню строки экспортирует одно событие.</p><p>Для сетевых событий пункт называется <strong>Export request &amp; response</strong>: события <strong>Send request</strong> и <strong>Receive response</strong> одного запроса экспортируются вместе в одном файле, поэтому запрос и ответ никогда не разделяются.</p><h3 id="изменения-pinia-при-частичном-экспорте" tabindex="-1">Изменения Pinia при частичном экспорте <a class="header-anchor" href="#изменения-pinia-при-частичном-экспорте" aria-label="Permalink to &quot;Изменения Pinia при частичном экспорте&quot;">​</a></h3><p>Событие <strong>Change store</strong> — дифф относительно предыдущего события того же стора. Если предыдущее событие не попало в экспорт (выбор строк, фильтр или одно событие), экспортируемое изменение дополнительно несёт полное состояние после него и старые значения изменённых полей, поэтому <strong>Before</strong> / <strong>After</strong> доступны и в файле.</p><h3 id="фаилы" tabindex="-1">Файлы <a class="header-anchor" href="#фаилы" aria-label="Permalink to &quot;Файлы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Экспорт</th><th>Имя файла</th></tr></thead><tbody><tr><td><strong>Export Logs</strong></td><td><code>logs_&lt;дата&gt;_&lt;время&gt;.html</code></td></tr><tr><td>Сетевая пара</td><td><code>log_network_&lt;дата&gt;_&lt;время&gt;.html</code></td></tr><tr><td>Другое одиночное событие</td><td><code>log_&lt;тип&gt;_&lt;дата&gt;_&lt;время&gt;.html</code></td></tr></tbody></table><p>Данные маскируются в момент записи, поэтому в файлах те же замаскированные значения, что и в интерфейсе (см. <a href="./settings.html#data-masking">Настройки логов</a>).</p><hr><h2 id="html-отчет" tabindex="-1">HTML-отчёт <a class="header-anchor" href="#html-отчет" aria-label="Permalink to &quot;HTML-отчёт&quot;">​</a></h2><p><strong>HTML</strong>-отчёт — один самодостаточный файл: стили, скрипты, иконка приложения и данные событий встроены внутрь. Отчёт в тёмной теме, не загружает внешние ресурсы и открывается с диска без интернета.</p><h3 id="боковая-панель" tabindex="-1">Боковая панель <a class="header-anchor" href="#боковая-панель" aria-label="Permalink to &quot;Боковая панель&quot;">​</a></h3><ul><li><strong>Report</strong> — <strong>Overview</strong> и <strong>All events</strong> с общим количеством;</li><li>разделы по типам со счётчиками: <strong>Network</strong> (<strong>Send request</strong>, <strong>Receive response</strong>), <strong>Components</strong> (<strong>Change props</strong>, <strong>Emit</strong>), <strong>Pinia</strong> (<strong>Change store</strong>, <strong>Store action</strong>), <strong>Page</strong> (<strong>Navigation</strong>, <strong>JS error</strong>);</li><li>внизу — <strong>Download Vue Inspector</strong> со ссылкой на страницу проекта.</li></ul><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Сводные карточки: <strong>Events</strong>, <strong>Errors</strong>, <strong>Failed requests</strong>, время первого и последнего события, длительность; счётчики по типам; сведения об экспорте.</p><p>Карточки <strong>Events</strong>, <strong>Errors</strong> и <strong>Failed requests</strong> кликабельны: они открывают <strong>All events</strong> с соответствующим фильтром. Активный фильтр показывается чипом над списком; клик по чипу снимает фильтр.</p><h3 id="список-событии-и-детализация" tabindex="-1">Список событий и детализация <a class="header-anchor" href="#список-событии-и-детализация" aria-label="Permalink to &quot;Список событий и детализация&quot;">​</a></h3><ul><li>Поиск в верхней панели; при включённом <strong>in data</strong> поиск идёт и по данным событий.</li><li>Клик по строке открывает детализацию с теми же вкладками, что и в приложении (<strong>Overview</strong>, <strong>Params</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Changes</strong>, <strong>Before</strong> / <strong>After</strong>, <strong>State</strong>, <strong>Raw</strong> и т.д.).</li><li>Для сетевых событий кнопка рядом с <strong>Close</strong> переключает между запросом и его ответом.</li><li><strong>↑ / ↓</strong> — переход между событиями, <strong>Esc</strong> — закрыть детализацию.</li><li>Выбранный раздел и событие сохраняются в адресе (<code>#…</code>): ссылкой на конкретное событие можно поделиться, и она переживает перезагрузку.</li></ul><hr><h2 id="импорт" tabindex="-1">Импорт <a class="header-anchor" href="#импорт" aria-label="Permalink to &quot;Импорт&quot;">​</a></h2><p><strong>Import Logs</strong> открывает <strong>HTML</strong>-отчёт, экспортированный из вкладки <strong>Logs</strong>. Файлы <strong>JSON</strong> и <strong>HTML</strong> из предыдущих версий тоже открываются.</p><ul><li>Импортированные события показываются в отдельном режиме только для чтения. В баннере — имя файла, число событий и время экспорта.</li><li><strong>Back to live logs</strong> возвращает к живой записи; живые события не теряются, пока открыт файл.</li><li>Некорректные события пропускаются (их число показывается в сообщении об импорте).</li><li>HTML-файлы, которые не являются отчётом Logs, отклоняются с сообщением.</li><li>Импортированные данные повторно проходят через текущие настройки маскирования.</li></ul><p>В файлах предыдущих версий половины запроса и ответа сетевой записи снова объединяются в одну запись.</p><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./general.html">Работа с логами</a></li><li><a href="./settings.html">Настройки логов</a></li><li><a href="/qa-tools/docs/ru/network/export.html">Экспорт коллекций</a></li></ul>',39)])])}const u=r(n,[["render",a]]);export{c as __pageData,u as default};
